package com.sobrenaturaldirector.memory;
import java.util.*; import com.sobrenaturaldirector.derivation.Confidence;
public final class MemoryCandidate { private final String candidateId,type,subjectKey,deduplicationKey; private final long observedAt; private final double importance; private final RetentionClass retention; private final Confidence confidence; private final int occurrenceCount; public MemoryCandidate(String id,String type,String subject,long tick,double importance,RetentionClass retention,Confidence confidence,String dedup,int count){candidateId=id;this.type=type;subjectKey=subject;observedAt=tick;this.importance=importance;this.retention=retention;this.confidence=confidence;deduplicationKey=dedup;occurrenceCount=count;} public String getCandidateId(){return candidateId;} public String getType(){return type;} public String getSubjectKey(){return subjectKey;} public long getObservedAt(){return observedAt;} public double getImportance(){return importance;} public RetentionClass getRetention(){return retention;} public Confidence getConfidence(){return confidence;} public String getDeduplicationKey(){return deduplicationKey;} public int getOccurrenceCount(){return occurrenceCount;} }
